using UnityEditor;using UnityEngine;using System;using System.IO;using System.Linq;using Newtonsoft.Json;
namespace Xinghai.MapEditor.Editor {public static class AxesProof {public static void Run(){try{var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Fixtures/axes.fbx");var registry=ScriptableObject.CreateInstance<MapRegistry>();registry.bindings=new[]{new AssetBinding{assetId="axis-test",prefab=model}};var doc=new MapDocument{mapId="axes-proof",cells=new Cell[0],instances=new[]{new Placement{id="axis",assetId="axis-test",x=2,y=3,z=1,rotation=90,anchor=new[]{.25f,.25f,0f}}}};var module=MapBaker.Bake(doc,"Assets/Generated/axes-proof",registry);var expected=new System.Collections.Generic.Dictionary<string,Vector3>{{"SourceX",new Vector3(2.25f,1,3.75f)},{"SourceY",new Vector3(1.25f,1,2.75f)},{"SourceZ",new Vector3(2.25f,2,2.75f)}};foreach(var item in expected){var actual=module.GetComponentsInChildren<Transform>().Single(t=>t.name==item.Key).position;if(Vector3.Distance(actual,item.Value)>.001f)throw new Exception("Axis/anchor mismatch "+item.Key+" "+actual+" expected "+item.Value);}File.WriteAllText("../logs/axes-final.json",JsonConvert.SerializeObject(new{passed=true,rotation=90,anchor=new[]{.25,.25,0},fbxCorrectionDegrees=180,checkedAxes=3},Formatting.Indented));UnityEngine.Object.DestroyImmediate(registry);Debug.Log("XH_AXES_PASS");EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}}}
